using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using ImageMagick;
using ImageMagick.Drawing;
using PdfSharp.Fonts;
using PdfSharp.Pdf.IO;
namespace CremaTools;

public static class SelfTests
{
    public static async Task RunAsync()
    {
        GlobalFontSettings.FontResolver = new SystemFontResolver(); var root = Path.Combine(AppContext.BaseDirectory, "test-results"); Directory.CreateDirectory(root); UiChecks.Render(root); var log = new List<string>(); void Pass(string s) => log.Add("PASS " + s); void Assert(bool condition, string error) { if (!condition) throw new Exception(error); }
        var progress = new Progress<string>(); var input = Path.Combine(root, "photo.png"); using (var image = new MagickImage(MagickColors.White, 2400, 1600)) { image.Draw(new Drawables().FillColor(MagickColors.Blue).Rectangle(100, 100, 1400, 1000)); image.Write(input); }
        var output = Path.Combine(root, Guid.NewGuid().ToString("N")); Directory.CreateDirectory(output);
        foreach (string format in new[] { "JPEG", "PNG", "WebP", "HEIC", "TIFF", "BMP", "AVIF" }) { var result = FileEngine.ConvertFiles([input], output, format, 85, false, progress, default); Assert(result.Errors.Count == 0 && result.Files.Count == 1, format + ": " + string.Join(';', result.Errors)); using var decoded = new MagickImage(result.Files[0]); Assert(decoded.Width == 2400 && decoded.Height == 1600, "Image dimensions: " + format); if (format == "HEIC") { var back = FileEngine.ConvertFiles(result.Files, output, "JPEG", 85, false, progress, default); Assert(back.Files.Count == 1 && back.Errors.Count == 0, "HEIC to JPEG"); } Pass("image conversion " + format); }
        var pdf = FileEngine.ConvertFiles([input, input], output, "PDF (un document)", 85, false, progress, default); Assert(pdf.Files.Count == 1, "Combined PDF"); using (var document = PdfReader.Open(pdf.Files[0], PdfDocumentOpenMode.Import)) Assert(document.PageCount == 2, "PDF page count"); var jpg = FileEngine.ConvertFiles(pdf.Files, output, "JPEG", 85, false, progress, default); Assert(jpg.Files.Count == 2 && jpg.Errors.Count == 0, "PDF to JPEG pages"); Pass("images to PDF and both PDF pages to JPEG");
        foreach (var mode in new[] { "Images — Mail (1600 px)", "PDF — Optimisation sans perte", "PDF — Réduire fortement (pages en images)", "Archive ZIP", "Archive 7z" }) { var result = FileEngine.Compress(mode.StartsWith("PDF") ? pdf.Files : [input], output, mode, false, progress, default); Assert(result.Errors.Count == 0 && result.Files.Count == 1, mode + ": " + string.Join(';', result.Errors)); if (mode == "Archive ZIP") { using var archive = ZipFile.OpenRead(result.Files[0]); Assert(archive.Entries.Count == 1, "Zip count"); } Pass(mode); }
        var rename = Path.Combine(output, "rename"); Directory.CreateDirectory(rename); var a = Path.Combine(rename, "a.txt"); var b = Path.Combine(rename, "b.txt"); File.WriteAllText(a, "ALPHA"); File.WriteAllText(b, "BETA"); var plan = RenameEngine.Plan([a, b], "France {n}", 1, 3, "", "Ne pas classer"); Assert(plan[0].Nouveau == "France 001.txt", "Rename preview"); var journal = Path.Combine(output, "journal.json"); RenameEngine.Apply(plan, journal); Assert(File.ReadAllText(plan[0].Destination) == "ALPHA", "Rename apply"); RenameEngine.Recover(journal); Assert(File.Exists(a) && File.Exists(b), "Rename undo"); RenameEngine.Apply([new(a, b), new(b, a)], journal); Assert(File.ReadAllText(a) == "BETA", "Rename cycle"); RenameEngine.Recover(journal); Assert(File.ReadAllText(a) == "ALPHA", "Rename cycle undo"); bool collision = false; try { RenameEngine.Validate([new(a, b)]); } catch { collision = true; }
        Assert(collision, "Rename collision protection"); Pass("rename preview, apply, undo, cycle and collision protection");
        var vaultRoot = Path.Combine(output, "vaults"); Directory.CreateDirectory(vaultRoot); string secret = "Phrase secrète de test 2026 !"; using var vault = new VaultEngine(); string recovery = vault.Create(vaultRoot, "Profil test", secret), directory = vault.DirectoryPath; vault.Add(a, "Personnel"); vault.AddCategory("Société test"); vault.RenameCategory("Personnel", "Privé"); var backup = Path.Combine(output, "backup.cremavault"); vault.Backup(backup); var encrypted = File.ReadAllBytes(Path.Combine(directory, vault.Index.Files[0].Id + ".enc")); Assert(!Encoding.UTF8.GetString(encrypted).Contains("ALPHA"), "Vault plaintext leak"); vault.Lock(); bool wrong = false; try { vault.Unlock(directory, "wrong password"); } catch (CryptographicException) { wrong = true; }
        Assert(wrong && !vault.IsOpen, "Wrong password"); vault.Unlock(directory, secret); Assert(Encoding.UTF8.GetString(vault.Read(vault.Index.Files[0])) == "ALPHA", "Vault decrypt"); vault.Lock(); vault.Unlock(directory, recovery, true); vault.ChangePassword("Nouvelle phrase secrète test 2026 !"); vault.Lock(); vault.Unlock(directory, "Nouvelle phrase secrète test 2026 !"); var restored = VaultEngine.Restore(backup, vaultRoot); vault.Lock(); vault.Unlock(restored, secret); Assert(vault.Index.Files.Count == 1 && vault.Index.Files[0].Category == "Privé", "Restore"); var stored = Path.Combine(restored, vault.Index.Files[0].Id + ".enc"); var modified = File.ReadAllBytes(stored); modified[^1] ^= 1; File.WriteAllBytes(stored, modified); bool tampered = false; try { vault.Read(vault.Index.Files[0]); } catch (CryptographicException) { tampered = true; }
        Assert(tampered, "Vault integrity check"); Pass("vault encryption, incorrect password, recovery key, password change, backup restore, tamper rejection");
        ScannerEngine.WriteDocx(Path.Combine(output, "text.docx"), [("Page 1", "Été & France <2026>\nDeuxième ligne")]); using (var zip = ZipFile.OpenRead(Path.Combine(output, "text.docx"))) { Assert(zip.GetEntry("word/document.xml") is not null, "Word structure"); }
        Pass("DOCX file structure and XML escaping");
        var langs = ScannerEngine.Languages(); Assert(langs.Count > 0, "No OCR languages"); using (var bitmap = new MagickImage(MagickColors.White, 1800, 500)) { bitmap.Draw(new Drawables().Font("Arial").FontPointSize(90).FillColor(MagickColors.Black).Text(60, 180, "CREMATOOLS DOCUMENT TEST").Text(60, 320, "Facture numero 2026")); var ocrFile = Path.Combine(output, "ocr.png"); bitmap.Write(ocrFile); var scanWord = await ScannerEngine.Scan([ocrFile], output, "Word modifiable (.docx)", langs.FirstOrDefault(l => l.StartsWith("fr")) ?? langs[0], true, progress, default); Assert(scanWord.Errors.Count == 0 && scanWord.Files.Count == 1, "Scanner Word"); var scanPdf = await ScannerEngine.Scan([ocrFile], output, "PDF recherchable", langs.FirstOrDefault(l => l.StartsWith("fr")) ?? langs[0], true, progress, default); Assert(scanPdf.Errors.Count == 0 && scanPdf.Files.Count == 1, "Scanner searchable PDF: " + string.Join(";", scanPdf.Errors)); using (var searchable = PdfReader.Open(scanPdf.Files[0], PdfDocumentOpenMode.Import)) Assert(searchable.PageCount == 1 && searchable.Pages[0].Elements.GetDictionary("/Resources")!.Elements.ContainsKey("/Font"), "Searchable PDF text layer"); var recognized = await ScannerEngine.Recognize(bitmap.ToByteArray(MagickFormat.Png), langs.FirstOrDefault(l => l.StartsWith("fr")) ?? langs[0]); Assert(recognized.Text.Contains("CREMATOOLS", StringComparison.OrdinalIgnoreCase), "OCR recognition: " + recognized.Text); }
        Pass("Windows OCR actual text recognition: " + string.Join(',', langs));
        await UpdateChecks.Run(); Pass("signed update manifest, tamper rejection, corrupted download rejection, verified download staging (no installer executed)"); File.WriteAllLines(Path.Combine(root, "test-report.txt"), log);
    }
}
